"function collectModal() {
    return {
      id:          modalId  ? modalId.value.trim()   : '',
      label:       modalLabel? modalLabel.value.trim(): '',
      // '' is the "— No site —" option; the server maps it to null.
      // siteIds, ordered with the primary first — that order IS the primary, and
      // the server keeps the scalar siteId in step as the rollback mirror, so
      // the client no longer sends it.
      // REORDERED, NEVER REWRITTEN. This modal no longer edits membership — that
      // is an authorization decision and lives in Access Management — so the
      // list sent back is the device's OWN stored list with the chosen primary
      // moved to the front, because position 0 is what the store reads as
      // primary.
      //
      // It is built from the stored record rather than from the picker's
      // options on purpose. A site deleted since the device was filed has no
      // name and is absent from the picker; rebuilding from the options would
      // silently drop it from the device. Reordering cannot.
      //
      // A device the client has not loaded sends undefined, which the server
      // reads as "leave membership alone" — the safe answer, and the reason
      // this is not `|| []`.
      siteIds:     (function () {
        var _id  = modalId ? modalId.value.trim() : '';
        var _rec = _id ? _routers.filter(function (r) { return r.id === _id; })[0] : null;
        if (!_rec) return undefined;
        var have = Array.isArray(_rec.siteIds) ? _rec.siteIds.slice()
                 : (_rec.siteId ? [_rec.siteId] : []);
        var prim = $('rtrModalPrimarySite') ? $('rtrModalPrimarySite').value : '';
        if (prim && have.indexOf(prim) !== -1) {
          have = [prim].concat(have.filter(function (id) { return id !== prim; }));
        }
        return have;
      }()),
      // Only ever `place`. Never `auto`: the store reads an absent `auto` as
      // "keep what you learned", so sending one here would let a save race the
      // background refresh and discard it.
      geo:         { place: _geoPicker ? _geoPicker.get() : null },
      host:        modalHost ? modalHost.value.trim() : '',
      port:        modalPort ? parseInt(modalPort.value, 10) : 8729,
      username:    modalUser ? modalUser.value.trim() : 'admin',
      password:    modalPass ? modalPass.value        : '',
      defaultIf:   modalIf  ? modalIf.value.trim()   : 'ether1',
      pingTarget:  modalPing? modalPing.value.trim()  : '1.1.1.1',
      tls:         modalTls ? modalTls.checked        : true,
      tlsInsecure: modalTlsI? modalTlsI.checked       : false,
      bwDownMbps: (function(){
        var v = parseInt(modalBwDown ? modalBwDown.value : '1', 10) || 1;
        return (modalBwDownU && modalBwDownU.value === 'gbps') ? v * 1000 : v;
      }()),
      bwUpMbps: (function(){
        var v = parseInt(modalBwUp ? modalBwUp.value : '1', 10) || 1;
        return (modalBwUpU && modalBwUpU.value === 'gbps') ? v * 1000 : v;
      }()),
      alertsEnabled:       !!(modalAlerts && modalAlerts.checked),
      connDownThresholdSec:(function(){ var n = parseInt(modalDownThresh ? modalDownThresh.value : '30', 10); return (n >= 0 && n <= 300) ? n : 30; }()),
      collection: (function () {
        var toggles = _collToggles();
        // The grid is fetched, so it can be empty when the modal has only just
        // opened. An empty grid yields off: [] — which the server would read as
        // "enable everything" and wipe the router's disabled collectors. Omit
        // the whole block instead: _normalizeCollection treats undefined as
        // "keep what is stored", which is exactly what we mean.
        if (!toggles.length) return undefined;
        var off = toggles.filter(function (t) { return !t.checked; })
                         .map(function (t) { return t.getAttribute('data-coll'); });
        // Server normalisation drops a block carrying no information, so sending
        // the defaults is harmless and leaves routers.json unchanged.
        return { mode: modalMode ? modalMode.value : 'stream', off: off };
      })(),
    };
  }"

