  var VIEW_PRESETS = {
    home:     ['wifi', 'wireless', 'interfaces', 'dhcp', 'connections', 'bandwidth'],
    standard: ['wifi', 'wireless', 'interfaces', 'dhcp', 'connections', 'bandwidth',
