    results = [];
    active = -1;
    inputEl.setAttribute('aria-expanded', 'false');
  }

  function commit(place) {
    chosen = place || null;
    previewOnly = false;                 // a commit is always the user's own
    inputEl.value = chosen ? _fmtPlace(chosen) : '';
    closeList();
    if (opts.onChange) opts.onChange(chosen);
  }

  /* Put the box back to whatever is actually committed.
   *
   * This is what guarantees typed text never becomes a location, and it replaces
   * an earlier attempt at the same guarantee that made the field readonly once
   * something was picked. That version enforced the rule by making the field a
   * dead end: with a town already set you could not type to choose a different
   * one, and the only way out was a button labelled "Use automatic" — not where
   * anyone looks for "change the town".
   *
   * Deliberately not commit(): restoring is not a choice, so it must leave
   * previewOnly alone or a previewed automatic location would silently become a
   * manual override just because someone clicked into the box and out again. */
  function restoreText() {
    inputEl.value = chosen ? _fmtPlace(chosen) : '';
  }

  function renderList() {
    if (!results.length) {
      listEl.innerHTML = '<div class="cpick-empty">'
        + (unavailable ? 'City search is unavailable on this install.' : 'No matching town.')
        + '</div>';
      listEl.hidden = false;
      inputEl.setAttribute('aria-expanded', 'true');
      return;
    }
    listEl.innerHTML = results.map(function (p, i) {
      // Place names come from a local database rather than a user, but they are
      // still being put into innerHTML, and the esc() rule has no exceptions.
      return '<div class="cpick-opt' + (i === active ? ' is-active' : '') + '" role="option"'
        + ' data-i="' + i + '">' + esc(p.name)
        + '<span class="cpick-cc">' + esc([p.region, p.cc].filter(Boolean).join(' ')) + '</span></div>';
    }).join('');
    listEl.hidden = false;
    inputEl.setAttribute('aria-expanded', 'true');
  }

  function search(q) {
    var mine = ++seq;
    fetch('/api/cities?q=' + encodeURIComponent(q), { credentials: 'same-origin' })
      .then(function (r) { return r.json(); })
      .then(function (j) {
        if (mine !== seq) return;                 // a newer keystroke already won
        unavailable = !!(j && j.unavailable);
        results = (j && j.cities) || [];
        active = results.length ? 0 : -1;
        renderList();
      })
      .catch(function () { if (mine === seq) closeList(); });
  }

  inputEl.addEventListener('input', function () {
    var q = inputEl.value.trim();
    if (timer) clearTimeout(timer);
    if (q.length < 2) { closeList(); return; }
    timer = setTimeout(function () { search(q); }, 250);
  });

  inputEl.addEventListener('focus', function () {
    // Select what is there so the first keystroke replaces it — the common case
    // is "this is wrong, let me pick another", not "let me edit these letters".
    if (inputEl.value) inputEl.select();
  });

  inputEl.addEventListener('keydown', function (e) {
    if (listEl.hidden || !results.length) {
      if (e.key === 'Escape') { restoreText(); inputEl.blur(); }
      return;
    }
    if (e.key === 'ArrowDown')      { e.preventDefault(); active = (active + 1) % results.length; renderList(); }
    else if (e.key === 'ArrowUp')   { e.preventDefault(); active = (active - 1 + results.length) % results.length; renderList(); }
    else if (e.key === 'Enter')     { e.preventDefault(); if (results[active]) commit(results[active]); }
    else if (e.key === 'Escape')    { e.preventDefault(); closeList(); restoreText(); }
    else if (e.key === 'Tab')       { closeList(); }   // a half-typed name is never a place
  });

  listEl.addEventListener('mousedown', function (e) {
    // mousedown, not click: blur would close the list first and eat the click.
    var opt = e.target.closest('.cpick-opt');
    if (!opt) return;
    e.preventDefault();
    commit(results[parseInt(opt.getAttribute('data-i'), 10)]);
  });

  inputEl.addEventListener('blur', function () {
    // Delayed, because a click on an option fires blur before the option's
    // handler runs. Whatever half-typed string is in the box goes back to the
    // committed place — leaving it would show a town that was never chosen.
    setTimeout(function () {
      if (!listEl.hidden) closeList();
      restoreText();
    }, 150);
  });

  if (opts.clearEl) {
    opts.clearEl.addEventListener('click', function () {
      commit(null);
      inputEl.focus();
    });
  }

  return {
    // The value to submit. Null while the box is only previewing an automatic
    // location, so an untouched field means "no override".
    get: function () { return previewOnly ? null : chosen; },
    set: function (place) { commit(place || null); },
    /* Show a location the server worked out, editable but not yet an override.
       Typing over it or picking from the list turns it into one. */
    preview: function (place) {
      commit(place || null);
      previewOnly = !!place;                 // a suggestion, not a commitment
    },
    clear: function () { commit(null); },
    isPreview: function () { return previewOnly; },
  };
}

/* ══════════════════════════════════════════════════════════════════════════════
   Routers page — Map view (issue #96)

   No tile server: the CSP allows nothing but 'self', and a map that phoned an
   external host would leak where every site is. Instead this reuses the country
   geometry the Connections page already builds and publishes as
   window._worldMapPathDs, making this its third consumer after dc-worldMap.

   Everything the payload cannot change — the zoom transform, a pinned popover —
   is deliberately kept out of the data path, because rows arrive every two
   seconds and a view that reset itself twice a second would be unusable.
   ═══════════════════════════════════════════════════════════════════════════ */

function _renderRoutersMap(rows) {
  if (window._rtrMapApply) window._rtrMapApply(rows);
}

(function () {
  var svg = $('routersMap');
  if (!svg) return;

  var NS = 'http://www.w3.org/2000/svg';
  var W = 1000, H = 500;
  var MIN_SCALE = 1, MAX_SCALE = 8;
  var BASE_R = 5;        // marker radius in screen px, held constant by /scale
  var GRID = 6;          // co-location bucket size, ~2 marker diameters at 1x

  var markerLayer = null, badgeLayer = null;
  var ready = false, pending = null;
  var scale = 1, tx = 0, ty = 0;
  var els = {};          // groupKey -> { g, ripple, dot, count }
  var pinned = null;     // groupKey whose popover is held open
  var lastById = {};     // routerId -> row, for the popover's contents
  var lastGroups = {};   // groupKey -> group

  var pop = $('rtrMapPop');
  var tray = $('rtrMapTray');
  var viewport = $('rtrMapViewport');

  /* Plain equirectangular, identical to the Connections map's — the country
     paths are already projected this way, so markers must use the same one. */
  function project(lon, lat) {
    return [(lon + 180) * (W / 360), (90 - lat) * (H / 180)];
  }

  function el(name, attrs) {
    var e = document.createElementNS(NS, name);
    for (var k in attrs) if (attrs.hasOwnProperty(k)) e.setAttribute(k, attrs[k]);
    return e;
  }

  // ── Build the backdrop once ────────────────────────────────────────────────
  function init() {
    if (ready || !window._worldMapPathDs) return;
    var countryLayer = el('g', {});
    var frag = document.createDocumentFragment();
    Object.keys(window._worldMapPathDs).forEach(function (cc) {
      frag.appendChild(el('path', { d: window._worldMapPathDs[cc], class: 'map-country' }));
    });
    countryLayer.appendChild(frag);
    markerLayer = el('g', {});
    badgeLayer  = el('g', {});
    svg.appendChild(countryLayer);

    svg.appendChild(markerLayer);
    svg.appendChild(badgeLayer);
    ready = true;
    if (pending) { var p = pending; pending = null; apply(p); }
  }
  // Both lines, because the atlas fetch may land either side of this script —
  // the same pattern dc-worldMap uses.
  document.addEventListener('worldmap:ready', init);
  init();

  // ── Zoom and pan ──────────────────────────────────────────────────────────
  function clampTranslate(s, x, y) {
    var w = svg.clientWidth || 1000, h = svg.clientHeight || 500;
    var maxX = (s - 1) * w, maxY = (s - 1) * h;
    return [Math.min(0, Math.max(-maxX, x)), Math.min(0, Math.max(-maxY, y))];
  }

  function applyTransform() {
    svg.style.transform = 'translate(' + tx + 'px,' + ty + 'px) scale(' + scale + ')';
    resize();
    positionPop();
  }


  function setScale(next, cx, cy) {
    var s = Math.min(MAX_SCALE, Math.max(MIN_SCALE, next));
    if (s === scale) return;
    var rect = svg.getBoundingClientRect();
    var ox = cx === undefined ? rect.width / 2 : cx - rect.left;
    var oy = cy === undefined ? rect.height / 2 : cy - rect.top;
    // Keep the point under the cursor fixed while the scale changes.
    tx = ox - ((ox - tx) / scale) * s;
    ty = oy - ((oy - ty) / scale) * s;
    scale = s;
    var c = clampTranslate(scale, tx, ty); tx = c[0]; ty = c[1];
    applyTransform();
  }

  svg.addEventListener('wheel', function (e) {
    e.preventDefault();
    userMovedView();
    setScale(scale * (e.deltaY < 0 ? 1.2 : 1 / 1.2), e.clientX, e.clientY);
  }, { passive: false });

  var dragging = false, sx = 0, sy = 0, stx = 0, sty = 0, moved = false;
  svg.addEventListener('pointerdown', function (e) {
    dragging = true; moved = false;
    sx = e.clientX; sy = e.clientY; stx = tx; sty = ty;
    svg.classList.add('is-dragging');
    svg.setPointerCapture(e.pointerId);
  });
  svg.addEventListener('pointermove', function (e) {
    if (!dragging) return;
    var dx = e.clientX - sx, dy = e.clientY - sy;
    if (Math.abs(dx) > 3 || Math.abs(dy) > 3) { if (!moved) userMovedView(); moved = true; }
    var c = clampTranslate(scale, stx + dx, sty + dy);
    tx = c[0]; ty = c[1];
    applyTransform();
  });
  function endDrag(e) {
    if (!dragging) return;
    dragging = false;
    svg.classList.remove('is-dragging');
    try { svg.releasePointerCapture(e.pointerId); } catch (err) {}
  }
  svg.addEventListener('pointerup', endDrag);
  svg.addEventListener('pointercancel', endDrag);

  /* Frame the fleet rather than the planet.
     A world view is the right answer for routers on three continents and the
     wrong one for the far commoner case of a fleet inside a single country,
     where every marker lands in a few pixels and the user has to pan and zoom
     before the view says anything. Fitting happens once, on the first render
     that has markers, so it never fights a viewport the user has since moved. */
  /* Off unless it has been switched on. The map opens on the world rather than
     snapping to fit, and the frame button (↺) does it on demand. */
  var AF_KEY = 'mikrodash_map_autoframe';
  var autoFrame = false;
  try { autoFrame = localStorage.getItem(AF_KEY) === '1'; } catch (e) {}
  var lastPlaced = [];

  /* `persist` separates a deliberate press of the button from an implicit
     release caused by panning. Only the former is remembered: otherwise one
     accidental drag turns a default-on feature off forever, and the next time
     you open the map it silently no longer frames anything. */
  function setAutoFrame(on, persist) {
    autoFrame = !!on;
    if (persist) { try { localStorage.setItem(AF_KEY, autoFrame ? '1' : '0'); } catch (e) {} }
    var b = $('rtrMapAutoFrame');
    if (b) {
      b.classList.toggle('is-on', autoFrame);
      b.setAttribute('aria-pressed', autoFrame ? 'true' : 'false');
    }
    if (autoFrame) fitToMarkers(lastPlaced);
  }

  /* Panning or zooming by hand is an explicit statement about what you want to
     look at, so it switches Auto Frame off. Leaving it on would snap the view
     back on the next two-second tick, which reads as the map fighting you. */
  function userMovedView() { if (autoFrame) setAutoFrame(false, false); }

  function fitToMarkers(pts) {
    if (!pts.length) return;
    var w = svg.clientWidth || 1000, h = svg.clientHeight || 500;
    var ux = w / W, uy = h / H;                    // px per map unit
    var minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;
    pts.forEach(function (p) {
      minX = Math.min(minX, p.x); maxX = Math.max(maxX, p.x);
      minY = Math.min(minY, p.y); maxY = Math.max(maxY, p.y);
    });
    var pad = 45;                                  // map units, so one marker is not filling the card
    minX -= pad; maxX += pad; minY -= pad; maxY += pad;
    var s = Math.min(MAX_SCALE, Math.max(MIN_SCALE,
      Math.min(w / ((maxX - minX) * ux), h / ((maxY - minY) * uy))));
    scale = s;
    tx = w / 2 - ((minX + maxX) / 2) * ux * s;
    ty = h / 2 - ((minY + maxY) / 2) * uy * s;
    var c = clampTranslate(scale, tx, ty); tx = c[0]; ty = c[1];
    applyTransform();
  }

  if (viewport) {
    viewport.addEventListener('click', function (e) {
      var btn = e.target.closest('[data-map-zoom]');
      if (!btn) return;
      var what = btn.getAttribute('data-map-zoom');
      if (what === 'in')  { userMovedView(); setScale(scale * 1.4); }
      if (what === 'out') { userMovedView(); setScale(scale / 1.4); }
      /* Reset returns to the starting view: the whole world, no pan.
       *
       * It has to release Auto Frame as well. Otherwise, with AF on, the next
       * payload re-frames immediately and the button looks broken — which is
       * exactly how it looked when reset was wired to "frame all routers" and
       * the view was already framed. Framing is the AF button's job; this one
       * zooms out. */
      if (what === 'reset') {
        setAutoFrame(false, false);
        scale = 1; tx = 0; ty = 0;
        applyTransform();
      }
      if (what === 'autoframe') setAutoFrame(!autoFrame, true);
    });
  }

  // The markup ships in the off state, so a stored "on" has to be reflected on
  // load — otherwise the button reads as off while the map is still framing.
  if (autoFrame) setAutoFrame(true, false);

  /* Markers keep a constant screen size, so zooming separates a cluster instead
     of magnifying it. The accuracy ring is deliberately excluded — it represents
     real distance on the ground and should scale with the map. */
  function resize() {
    /* Marker radius depends on how many routers are in the group, so the data
       path owns it; re-deriving it here would need the group sizes and the two
       could disagree. Re-applying the last payload keeps every marker a constant
       size on screen as the zoom changes. */
    if (window._lastRtrRows) apply(window._lastRtrRows);
  }

  // ── Popover ───────────────────────────────────────────────────────────────
  function popHtml(r) {
    var g = r.geo || {};
    var up = r.uptime ? String(r.uptime) : '—';
    // Where the position came from, stated plainly and without alarm. The map
    // itself no longer distinguishes them.
    var from = g.source === 'manual' ? 'set here'
             : g.source === 'site'   ? 'from its site'
             : (g.wanIp ? 'from ' + esc(g.wanIp) : 'from its WAN address');
    var loc = esc(g.label || 'Unknown')
      + ' <span class="text-muted">(' + from + ')</span>';
    var canManage = !!(window._caps && window._caps.routers
      && (window._caps.routers.manageable || []).indexOf(r.id) !== -1);
    return '<div class="rmp-name"><span class="rtl-dot" style="background:'
      + (r.connected ? 'var(--accent-green,#2fb344)' : 'var(--accent-red,#f87171)')
      + '"></span>' + esc(r.label) + '</div>'
      + '<div class="rmp-grid">'
      + '<span>Host</span><b>' + esc(r.host) + '</b>'
      + '<span>CPU</span><b>' + (r.cpu == null ? '—' : r.cpu + '%') + '</b>'
      + '<span>Uptime</span><b>' + esc(up) + '</b>'
      + '<span>WAN</span><b>&#8595;' + (r.rxMbps == null ? '—' : r.rxMbps)
      + ' &#8593;' + (r.txMbps == null ? '—' : r.txMbps) + ' Mbps</b>'
      + (r.openAlerts ? '<span>Alerts</span><b style="color:var(--accent-amber,#f59f00)">' + r.openAlerts + '</b>' : '')
      + '</div>'
      + '<div class="rmp-loc">' + loc + '</div>'
      + (canManage ? '<button type="button" data-open-router="' + esc(r.id) + '">Open settings</button>' : '');
  }

  var hovered = null;

  /* A group of one shows the router. A group of several shows what is in it —
     the count on the marker says how many, and this says which, with a way into
     each one's settings. Without it a cluster would be a dead end. */
  function groupPopHtml(g) {
    if (g.routers.length === 1) return popHtml(g.routers[0]);
    var place = (g.routers[0].geo && g.routers[0].geo.label) || 'this location';
    var down = g.routers.filter(function (r) { return !r.connected; }).length;
    return '<div class="rmp-name">' + g.routers.length + ' routers</div>'
      + '<div class="rmp-loc" style="margin-top:.2rem;padding-top:0;border-top:0">'
      + esc(place)
      + (down ? ' <span style="color:var(--accent-err,#f87171)">— ' + down + ' offline</span>' : '')
      + '</div>'
      + '<div class="rmp-list">' + g.routers.map(function (r) {
          var can = !!(window._caps && window._caps.routers
            && (window._caps.routers.manageable || []).indexOf(r.id) !== -1);
          return '<div class="rmp-row"' + (can ? ' data-open-router="' + esc(r.id) + '"' : '')
            + '><span class="rtl-dot" style="background:'
            + (r.connected ? 'var(--accent-green,#2fb344)' : 'var(--accent-red,#f87171)')
            + '"></span><span class="rmp-rl">' + esc(r.label) + '</span>'
            + '<span class="rmp-rh">' + esc(r.host) + '</span></div>';
        }).join('') + '</div>';
  }

  function showPop(key, isPin) {
    var g = lastGroups[key];
    if (!g || !pop) return;
    pop.innerHTML = groupPopHtml(g);
    pop.hidden = false;
    pop.classList.toggle('is-pinned', !!isPin);
    positionPop();
  }
  function hidePop() {
    if (!pop || pinned) return;
    pop.hidden = true;
  }
  function positionPop() {
    var key = pinned || hovered;
    if (!pop || pop.hidden || !key || !els[key] || !viewport) return;
    var mr = els[key].dot.getBoundingClientRect();
    var vr = viewport.getBoundingClientRect();
    var left = mr.left - vr.left + mr.width / 2 + 12;
    var top  = mr.top - vr.top - 8;
    // Keep it inside the card rather than letting it spill off the right edge.
    left = Math.min(left, vr.width - pop.offsetWidth - 8);
    top  = Math.min(Math.max(top, 4), vr.height - pop.offsetHeight - 4);
    pop.style.left = Math.max(4, left) + 'px';
    pop.style.top  = Math.max(4, top) + 'px';
  }

  if (pop) {
    pop.addEventListener('click', function (e) {
      var b = e.target.closest('[data-open-router]');
      if (!b) return;
      if (window._rtrOpenModal) window._rtrOpenModal(b.getAttribute('data-open-router'));
    });
  }
  document.addEventListener('keydown', function (e) {
    if (e.key === 'Escape' && pinned) { pinned = null; hovered = null; if (pop) pop.hidden = true; }
  });

  // ── Fan-out ───────────────────────────────────────────────────────────────
  /* Several routers behind one WAN IP geolocate to the identical point. Spread
     them onto a small ring so each stays individually hoverable, with a count so
     the pile is legible before you zoom into it. Members are ordered by id, so a
     marker never swaps places between ticks. */
  /* Group routers that resolve to the same place.
   *
   * Several routers behind one WAN address share a coordinate exactly, and an
   * earlier version fanned them onto a small ring so each stayed clickable. On a
   * real fleet that read as three separate sites rather than one place with
   * three routers in it — the opposite of the truth. They now collapse into a
   * single marker carrying the count, and the popover lists what is inside.
   */
  function layout(located) {
    var buckets = {};
    located.forEach(function (r) {
      var p = project(r.geo.lon, r.geo.lat);
      var k = Math.round(p[0] / GRID) + ':' + Math.round(p[1] / GRID);
      if (!buckets[k]) buckets[k] = { key: k, x: 0, y: 0, routers: [] };
      buckets[k].routers.push(r);
      buckets[k].x += p[0];
      buckets[k].y += p[1];
    });
    return Object.keys(buckets).map(function (k) {
      var b = buckets[k];
      b.x /= b.routers.length;
      b.y /= b.routers.length;
      // Stable order, so a popover list does not reshuffle every two seconds.
      b.routers.sort(function (a, c) { return (a.label || '') < (c.label || '') ? -1 : 1; });
      return b;
    });
  }

  // ── The data path ─────────────────────────────────────────────────────────
  function apply(rows) {
    if (!ready) { pending = rows; return; }
    rows = rows || [];
    lastById = {};
    rows.forEach(function (r) { lastById[r.id] = r; });

    var located = rows.filter(function (r) { return r.geo && r.geo.lat != null && r.geo.lon != null; });
    var groups  = layout(located);
    lastGroups = {};
    groups.forEach(function (g) { lastGroups[g.key] = g; });
    var seen = {};

    /* One label per place. Keyed on the group, so three routers at one address
       write their town once — writing it three times would be exactly the noise
       the general city layer was removed for. */
    var labelled = groups.map(function (g) {
      return { text: (g.routers[0].geo && g.routers[0].geo.label) || '', x: g.x, y: g.y };
    }).filter(function (L) { return !!L.text; });

    /* Drop labels that would land on top of each other.
       At world zoom a European fleet writes several place names into the same
       centimetre and none of them is readable. Comparing anchor points is not
       enough — "Berlin, BE, DE" is many times wider than the gap between two
       capitals — so this compares the boxes the text will actually occupy.
       Everything is in map units divided by scale, i.e. fixed on screen, so
       zooming in separates the boxes and the hidden names return one by one. */
    (function () {
      var fsz = 8 / scale;
      var kept = [];
      labelled.forEach(function (L) {
        // 0.55em per character is a good enough advance width for a monospace
        // face; being slightly generous errs toward hiding, which is the safe
        // way to be wrong here.
        L.hw = (L.text.length * fsz * 0.55) / 2;
        L.hh = fsz * 0.75;
        L.ly = L.y + 11 / scale;              // just under the marker
        for (var i = 0; i < kept.length; i++) {
          var k = kept[i];
          if (Math.abs(k.x - L.x) < (k.hw + L.hw) && Math.abs(k.ly - L.ly) < (k.hh + L.hh)) return;
        }
        kept.push(L);
      });
      labelled = kept;
    }());

    groups.forEach(function (g) {
      var key = g.key;
      seen[key] = 1;
      var e = els[key];
      if (!e) {
        // Created once and then mutated. Rebuilding the SVG every two seconds
        // would drop hover state and fight the pointer.
        e = els[key] = {
          g: el('g', { class: 'rtrmap-marker' }),
          ripple: el('circle', { class: 'rtrmap-ripple' }),
          dot: el('circle', {}),
          count: el('text', { class: 'rtrmap-clustern' }),
        };
        /* Stagger the start so a fleet does not strobe in unison — a rack of
           routers all pulsing on the same beat reads as a warning rather than as
           a heartbeat. Derived from the key so it is stable across re-renders
           instead of jumping every two seconds. */
        var phase = 0;
        for (var ci = 0; ci < key.length; ci++) phase = (phase * 31 + key.charCodeAt(ci)) % 2600;
        e.ripple.style.animationDelay = '-' + phase + 'ms';
        e.g.appendChild(e.ripple);
        e.g.appendChild(e.dot);
        e.g.appendChild(e.count);
        markerLayer.appendChild(e.g);
        e.g.addEventListener('mouseenter', function () { hovered = key; showPop(key, false); });
        e.g.addEventListener('mouseleave', function () { hovered = null; hidePop(); });
        e.g.addEventListener('click', function (ev) {
          ev.stopPropagation();
          if (moved) return;                 // a drag that ended on a marker is not a click
          pinned = (pinned === key) ? null : key;
          if (pinned) showPop(key, true); else { pop.hidden = true; }
        });
      }

      /* Colour by the worst state in the group. A site with one router down is a
         site with a problem, and a green dot hiding a red one would defeat the
         only thing the map is really for. */
      var anyDown = g.routers.some(function (r) { return !r.connected; });
      var colour = anyDown ? 'var(--accent-red,#f87171)' : 'var(--accent-green,#2fb344)';
      var n = g.routers.length;
      /* Size carries the count as well as the number does: a place with twenty
         routers should look weightier than one with two, before you read
         anything. Square-root growth rather than linear, because area is what
         the eye judges — and capped, so one big site cannot swallow the map. */
      var rad = Math.min(16, BASE_R + 3.2 * Math.sqrt(Math.max(0, n - 1))) / scale;

      e.dot.setAttribute('cx', g.x);
      e.dot.setAttribute('cy', g.y);
      e.dot.setAttribute('r', rad);
      e.dot.setAttribute('stroke-width', 1.5 / scale);
      e.dot.setAttribute('fill', colour);
      e.dot.setAttribute('stroke', 'rgba(0,0,0,.45)');
      e.ripple.setAttribute('cx', g.x);
      e.ripple.setAttribute('cy', g.y);
      e.ripple.setAttribute('r', rad);
      e.ripple.setAttribute('fill', colour);

      if (n > 1) {
        e.count.setAttribute('x', g.x);
        e.count.setAttribute('y', g.y);
        // Shrink the glyphs as the number gets longer so "128" still fits the
        // circle it is written in.
        var digits = String(n).length;
        e.count.setAttribute('font-size',
          rad * (digits === 1 ? 1.15 : digits === 2 ? 0.95 : 0.72));
        e.count.textContent = String(n);
        e.count.style.display = '';
      } else {
        e.count.style.display = 'none';
      }
    });

    // Groups that left the payload — filtered out by the search, or no longer
    // visible to this session.
    Object.keys(els).forEach(function (key) {
      if (seen[key]) return;
      els[key].g.remove();
      delete els[key];
      if (pinned === key) { pinned = null; if (pop) pop.hidden = true; }
    });

    // Place names, sized against the zoom: in map units they would grow with the
    // transform until a town name spanned a continent.
    badgeLayer.innerHTML = '';
    labelled.forEach(function (L) {
      var t = el('text', { class: 'rtrmap-place', x: L.x, y: L.ly,
                           'font-size': 8 / scale, 'stroke-width': 2.5 / scale });
      t.textContent = L.text;
      badgeLayer.appendChild(t);
    });

    lastPlaced = groups;
    // While Auto Frame is on this runs on every payload, so adding a router or
    // narrowing the search re-frames to what is actually shown.
    if (autoFrame && groups.length) fitToMarkers(groups);

    // A pinned popover follows the data rather than the other way round: its
    // contents refresh so CPU and uptime stay live, but it never closes itself.
    if (pinned && lastGroups[pinned]) showPop(pinned, true);

    renderTray(rows.filter(function (r) { return !r.geo; }));
  }

  function renderTray(unlocated) {
    if (!tray) return;
    if (!unlocated.length) { tray.hidden = true; tray.innerHTML = ''; return; }
    tray.hidden = false;
    tray.innerHTML = '<span class="rmt-label">No location ('
      + unlocated.length + '):</span>'
      + unlocated.map(function (r) {
        return '<span class="rmt-pill" data-open-router="' + esc(r.id) + '" title="'
          + esc(r.host) + '"><span class="rtl-dot" style="background:'
          + (r.connected ? 'var(--accent-green,#2fb344)' : 'var(--accent-red,#f87171)')
          + '"></span>' + esc(r.label) + '</span>';
      }).join('')
      + '<span class="rmt-label" style="flex-basis:100%;margin-top:.25rem">'
      + 'Their WAN address is private or unroutable, so it cannot be geolocated. '
      + 'Set a town in the router’s settings, or give its site one.</span>';
  }

  if (tray) {
    tray.addEventListener('click', function (e) {
      var p = e.target.closest('[data-open-router]');
      if (p && window._rtrOpenModal) window._rtrOpenModal(p.getAttribute('data-open-router'));
    });
  }

  // Clicking empty map releases a pinned popover.
  svg.addEventListener('click', function () {
    if (moved) return;
    if (pinned) { pinned = null; if (pop) pop.hidden = true; }
  });

  window._rtrMapApply = apply;
}());

/* ── Frequency Analyzer ───────────────────────────────────────────────────────
   The only place the dashboard drives a disruptive action: a frequency scan
   takes the chosen radio off the air and drops every client on it. The server
   bounds that (src/wifiScan.js); this side is responsible for saying so plainly
   before the button is pressed, and for never leaving the modal claiming to be
   scanning when it is not. */
(function () {
  var modal   = $('faModal');
  var openBtn = $('faOpenBtn');
  if (!modal || !openBtn) return;

  var ifaceSel = $('faIface'), durSel = $('faDuration');
  var scanBtn  = $('faScanBtn'), stopBtn = $('faStopBtn'), statusEl = $('faStatus');
  var gridEl   = $('faChanGrid'), emptyEl = $('faEmpty'), spinEl = $('faSpin');

  var FA_FLOOR_DBM = -100;  // bar base and y-axis minimum
  var _chart = null;        // built on open — a canvas sized while display:none is 0x0
  var _rows  = [];
  var _state = { scanning: false, scanId: null, currentChannelMhz: null, endsAt: 0 };
  var _tick  = null;
  var _ifaceList = [];

  // Green (open) through red (congested). Same shape as pingColor(): a small
  // ladder of thresholds rather than a gradient, so two channels a percent apart
  // do not read as meaningfully different.
  function congestionColour(load, alpha) {
    var a = alpha === undefined ? 0.85 : alpha;
    if (load == null)  return 'rgba(148,163,190,' + (a * 0.45) + ')';
    if (load < 20)     return 'rgba(74,222,128,' + a + ')';
    if (load < 40)     return 'rgba(163,230,53,' + a + ')';
    if (load < 60)     return 'rgba(251,191,36,' + a + ')';
    if (load < 80)     return 'rgba(251,146,60,' + a + ')';
    return 'rgba(248,113,113,' + a + ')';
  }

  function setStatus(text, scanning) {
    statusEl.textContent = text;
    statusEl.classList.toggle('is-scanning', !!scanning);
  }

  function setScanning(on) {
    _state.scanning = on;
    scanBtn.style.display = on ? 'none' : '';
    stopBtn.style.display = on ? '' : 'none';
    if (spinEl) spinEl.classList.toggle('on', on);
    ifaceSel.disabled = on;
    durSel.disabled = on;
    if (_tick) { clearInterval(_tick); _tick = null; }
    if (on) {
      _tick = setInterval(function () {
        var left = Math.max(0, Math.ceil((_state.endsAt - Date.now()) / 1000));
        // Past zero the router owes us a result; say we are waiting rather than
        // counting into negative numbers.
        setStatus(left > 0 ? ('Scanning… ' + left + 's — clients disconnected') : 'Finishing…', true);
      }, 250);
    }
  }

  /* Best channel: lowest load, tie-broken by fewest networks.
     Note for 2.4GHz: channels there overlap, so the lowest-load channel can sit
     between two busy ones. Restricting the pick to 1/6/11 would avoid that; it
     is not done here because the metric shown is exactly what the router
     measured, with nothing inferred on top. */
  function bestChannel(rows) {
    var scored = rows.filter(function (r) { return r.load != null; });
    if (!scored.length) return null;
    return scored.slice().sort(function (a, b) {
      if (a.load !== b.load) return a.load - b.load;
      return (a.nets || 0) - (b.nets || 0);
    })[0];
  }

  function renderStats() {
    var cur = _rows.filter(function (r) { return r.ch === _state.currentChannelMhz; })[0];
    var best = bestChannel(_rows);
    var nf = _rows.map(function (r) { return r.nf; }).filter(function (v) { return v != null; });
    var nets = _rows.reduce(function (n, r) { return n + (r.nets || 0); }, 0);

    var unit = function (u) { return '<span class="fa-stat-unit">' + u + '</span>'; };
    $('faCurChan').innerHTML   = (_state.currentChannelMhz || '&mdash;') + unit('MHz');
    $('faNetworks').innerHTML  = _rows.length ? String(nets) : '&mdash;';
    $('faCongestion').innerHTML = (cur && cur.load != null ? cur.load : '&mdash;') + unit('%');
    $('faBestChan').innerHTML  = (best ? best.ch : '&mdash;') + unit('MHz');
    // Median, not mean: one spurious bin should not move the reported floor.
    var median = nf.length ? nf.slice().sort(function (a, b) { return a - b; })[Math.floor(nf.length / 2)] : null;
    $('faNoise').innerHTML     = (median == null ? '&mdash;' : median) + unit('dBm');

    if (cur && cur.load != null) {
      $('faCongestion').style.color = congestionColour(cur.load, 1);
    } else {
      $('faCongestion').style.color = '';
    }
  }

  function renderGrid() {
    if (!_rows.length) { gridEl.innerHTML = ''; return; }
    gridEl.innerHTML = _rows.map(function (r) {
      var isCur = r.ch === _state.currentChannelMhz;
      var load  = r.load == null ? null : r.load;
      return '<div class="fa-chan' + (isCur ? ' is-current' : '') + '"' +
             ' style="background:' + congestionColour(load, 0.22) +
             ';border-color:' + congestionColour(load, 0.5) + '"' +
             ' title="' + esc(String(r.chRaw || r.ch)) + (r.nets != null ? (' · ' + r.nets + ' networks') : '') + '">' +
        '<div class="fa-chan-num">' + (r.chNum == null ? '&mdash;' : ('ch ' + r.chNum)) + '</div>' +
        '<div class="fa-chan-freq">' + r.ch + '</div>' +
        '<div class="fa-chan-load" style="color:' + congestionColour(load, 1) + '">' +
          (load == null ? '&mdash;' : (load + '%')) + '</div>' +
      '</div>';
    }).join('');
  }

  /* A vertical band marking the radio's own channel, drawn UNDER the bars so it
     locates you without hiding the reading. This replaces colouring that bar
     blue, which marked the channel at the cost of the one congestion colour you
     most want to see — your own. */
  var faChannelBand = {
    id: 'faChannelBand',
    beforeDatasetsDraw: function (chart) {
      if (_state.currentChannelMhz == null) return;
      var idx = chart.data.labels.indexOf(_state.currentChannelMhz);
      if (idx < 0) return;
      // Take the width from the bar itself so the band lines up exactly, rather
      // than from the category spacing — Chart.js insets bars within their
      // category, so a category-wide band would sit visibly proud of them.
      var el = (chart.getDatasetMeta(0).data || [])[idx];
      var xs = chart.scales.x;
      if (!el && !xs) return;
      var x = el ? el.x : xs.getPixelForValue(idx);
      var w = (el && el.width) ? el.width
        : Math.max(10, Math.min(chart.data.labels.length > 1
            ? Math.abs(xs.getPixelForValue(1) - xs.getPixelForValue(0)) : 18, 44));
      var a = chart.chartArea, ctx = chart.ctx;
      ctx.save();
      ctx.fillStyle = 'rgba(56,189,248,.20)';
      ctx.fillRect(x - w / 2, a.top, w, a.bottom - a.top);
      ctx.strokeStyle = 'rgba(56,189,248,.85)';
      ctx.lineWidth = 1.5;
      ctx.strokeRect(x - w / 2, a.top, w, a.bottom - a.top);
      ctx.restore();
    },
  };

  function makeChart() {
    if (_chart) { _chart.destroy(); _chart = null; }
    var ctx = $('faSpectrum');
    if (!ctx || typeof Chart === 'undefined') return;
    _chart = new Chart(ctx, {
      type: 'bar',
      data: { labels: [], datasets: [
        // Signal power as bars, each coloured by that channel's congestion, so
        // one glance answers both "is anything there" and "how busy is it".
        // Congestion stays on the chart as the bar colour, and is readable as a
        // number in the tooltip and the grid above — it does not need a line of
        // its own competing with the signal trace.
        { label: 'Signal power', data: [], yAxisID: 'y', order: 3,
          backgroundColor: [], borderRadius: 2, borderSkipped: false },
        // The reference the signal is measured against.
        { label: 'Noise floor', type: 'line', data: [], yAxisID: 'y', order: 2,
          borderColor: 'rgba(148,163,190,.75)', borderDash: [4, 3],
          borderWidth: 1.5, pointRadius: 0, tension: 0.25, fill: false, spanGaps: true },
        // Airtime load on its own axis. It used to be encoded only as bar
        // colour, so a channel read as orange without reading as 44%. Stepped
        // because load is measured per channel; interpolating between them
        // would draw values the router never reported.
      ] },
      plugins: [faChannelBand],
      options: {
        responsive: true, maintainAspectRatio: false, animation: false,
        interaction: { mode: 'index', intersect: false },
        plugins: {
          legend: {
            display: true,
            labels: {
              color: 'rgba(148,163,190,.8)', boxWidth: 10, font: { size: 10 }, usePointStyle: true,
              // The current-channel band is drawn by a plugin, so it has no
              // dataset for the legend to pick up. Append it by hand, or the
              // one mark people ask about is the one nothing explains.
              generateLabels: function (chart) {
                var items = Chart.defaults.plugins.legend.labels.generateLabels(chart);
                items.push({
                  text: 'Active Channel',
                  fillStyle: 'rgba(56,189,248,.35)',
                  strokeStyle: 'rgba(56,189,248,.85)',
                  lineWidth: 1.5, pointStyle: 'rect', hidden: false,
                });
                return items;
              },
            },
            // That appended item has no datasetIndex; the default handler would
            // throw trying to toggle a dataset that does not exist.
            onClick: function (e, item, legend) {
              if (item.datasetIndex === undefined) return;
              Chart.defaults.plugins.legend.onClick.call(this, e, item, legend);
            },
          },
          tooltip: {
            // Every column the scan measured. It used to show the frequency and
            // nothing else, throwing away five values per channel.
            callbacks: {
              title: function (c) {
                var r = _rows[c[0].dataIndex];
                return r ? (r.ch + ' MHz' + (r.chNum != null ? '  (ch ' + r.chNum + ')' : '')) : '';
              },
              label: function () { return null; },
              afterBody: function (c) {
                var r = _rows[c[0].dataIndex];
                if (!r) return [];
                var out = [];
                if (r.load   != null) out.push('Load        ' + r.load + '%');
                if (r.nets   != null) out.push('Networks    ' + r.nets);
                if (r.nf     != null) out.push('Noise floor ' + r.nf + ' dBm');
                if (r.maxSig != null) out.push('Max signal  ' + r.maxSig + ' dBm');
                if (r.minSig != null) out.push('Min signal  ' + r.minSig + ' dBm');
                if (r.ch === _state.currentChannelMhz) out.push('— this radio —');
                return out;
              },
            },
          },
        },
        scales: {
          x: { ticks: { color: 'rgba(148,163,190,.5)', font: { size: 9 }, maxRotation: 0, autoSkipPadding: 12 },
               grid: { display: false } },
          y: { position: 'left', min: FA_FLOOR_DBM, max: -20,
               title: { display: true, text: 'dBm', color: 'rgba(148,163,190,.5)', font: { size: 9 } },
               grid: { color: 'rgba(99,130,190,.08)' },
               ticks: { color: 'rgba(148,163,190,.5)', font: { size: 9 } } },
        },
      },
    });
  }

  function renderChart() {
    if (!_chart) return;
    _chart.data.labels = _rows.map(function (r) { return r.ch; });
    // Bar height is signal strength; its colour carries congestion, so one
    // glance answers both "is anything there" and "how busy is it".
    // Floating bars [base, top]. Signal is negative dBm, so a plain value would
    // hang down from the 0 line; anchoring each bar at the chart floor makes it
    // rise out of the noise the way a spectrum display should. A channel where
    // nothing was detected gets no bar rather than a fabricated one.
    _chart.data.datasets[0].data = _rows.map(function (r) {
      return r.maxSig == null ? null : [FA_FLOOR_DBM, r.maxSig];
    });
    _chart.data.datasets[0].backgroundColor = _rows.map(function (r) {
      return congestionColour(r.load);
    });
    _chart.data.datasets[1].data = _rows.map(function (r) { return r.nf; });
    _chart.update('none');
  }

  function render() {
    emptyEl.style.display = _rows.length ? 'none' : '';
    renderStats(); renderGrid(); renderChart();
  }

  function open() {
    modal.classList.add('open');
    _rows = []; _state.scanId = null;
    render();
    makeChart();               // only now is the canvas measurable
    setStatus('Idle', false);
    socket.emit('wifiscan:interfaces');
  }

  function close() {
    modal.classList.remove('open');
    // Best effort only. The server's wall-clock stop is what actually bounds the
    // outage; this just avoids leaving a radio down because somebody wandered off.
    if (_state.scanning) socket.emit('wifiscan:stop', { scanId: _state.scanId });
    setScanning(false);
    if (_chart) { _chart.destroy(); _chart = null; }
  }

  /* Measured, not assumed: scanning a radio with clients on it dropped all 15
     within 2 seconds, held them at zero for the full 30, and they took over 15
     seconds to start returning. Scanning an idle radio dropped nothing. So the
     warning states which of the two you are about to do. */
  function updateWarning() {
    var el = $('faWarnText');
    if (!el) return;
    var rec = _ifaceList.filter(function (i) { return i.name === ifaceSel.value; })[0];
    var n = rec ? (rec.clients || 0) : 0;
    if (!rec) {
      el.innerHTML = 'Scanning takes the selected radio off the air.';
      return;
    }
    if (n === 0) {
      el.innerHTML = 'This radio has <b>no clients connected</b>, so scanning it should ' +
        'interrupt nobody. Other radios on this router are unaffected.';
    } else {
      el.innerHTML = 'Scanning takes this radio off the air. Its <b>' + n + ' connected ' +
        (n === 1 ? 'client' : 'clients') + ' will be disconnected</b> for the duration of the ' +
        'scan, including any on its other SSIDs, and may take some seconds to return afterwards. ' +
        'Other radios on this router are unaffected.';
    }
  }
  ifaceSel.addEventListener('change', updateWarning);

  openBtn.addEventListener('click', open);
  modal.addEventListener('click', function (e) { if (e.target === modal) close(); });
  var closeX = modal.querySelector('[data-modal-close]');
  if (closeX) closeX.addEventListener('click', close);
  document.addEventListener('keydown', function (e) {
    if (e.key === 'Escape' && modal.classList.contains('open')) close();
  });

  scanBtn.addEventListener('click', function () {
    if (!ifaceSel.value) return;
    socket.emit('wifiscan:start', { iface: ifaceSel.value, durationSec: parseInt(durSel.value, 10) });
  });
  stopBtn.addEventListener('click', function () {
    socket.emit('wifiscan:stop', { scanId: _state.scanId });
  });

  socket.on('wifiscan:interfaces', function (d) {
    if (!d) return;
    // The button exists only for someone who may actually scan.
    openBtn.style.display = (d.permitted && (d.interfaces || []).length) ? '' : 'none';
    _ifaceList = d.interfaces || [];
    var list = _ifaceList;
    var keep = ifaceSel.value;
    // The count is the whole radio's, virtual APs included. Without it the
    // picker gives no clue which radio is idle and which carries the network:
    // measured on a live fleet, the two obvious-looking radios had zero clients
    // and the other two had every one of them.
    ifaceSel.innerHTML = list.map(function (i) {
      var n = i.clients || 0;
      return '<option value="' + esc(i.name) + '">' + esc(i.name) +
             ' · ' + (n ? (n + (n === 1 ? ' client' : ' clients')) : 'no clients') + '</option>';
    }).join('');
    if (keep && list.some(function (i) { return i.name === keep; })) ifaceSel.value = keep;
    if (!list.length) {
      ifaceSel.innerHTML = '<option disabled selected>No scannable radio</option>';
      scanBtn.disabled = true;
      emptyEl.textContent = 'This router reports no radio that can be scanned. ' +
        'Virtual APs, CAPsMAN-managed radios and the legacy wireless package are not supported.';
    } else {
      scanBtn.disabled = false;
    }
    updateWarning();
  });

  socket.on('wifiscan:state', function (d) {
    if (!d) return;
    _state.scanId = d.scanId;
    _state.currentChannelMhz = d.currentChannelMhz;
    _state.endsAt = d.endsAt;
    _rows = d.rows || [];
    setScanning(!!d.scanning);
    render();
  });

  socket.on('wifiscan:rows', function (d) {
    if (!d || d.scanId !== _state.scanId) return;
    _rows = d.rows || [];
    render();
  });

  socket.on('wifiscan:done', function (d) {
    if (!d) return;
    _rows = d.rows || _rows;
    setScanning(false);
    render();
    // A dashboard-enforced stop still produced valid readings. Reporting it as
    // an error would teach people to distrust correct data.
    var msg = {
      complete:        'Scan complete',
      timeout:         'Scan complete',
      aborted:         'Scan stopped',
      disconnected:    'Router went away mid-scan',
      'session-restart': 'Scan interrupted by a router session restart',
      error:           'Scan failed',
    }[d.reason] || 'Scan ended';
    if (!d.rows || !d.rows.length) {
      // Distinguish "the scan ran and the band is empty" — which cannot happen,
      // every band has a noise floor — from "the router returned nothing". The
      // second is the real case, and calling it success sends people hunting
      // for a quiet channel that was never measured.
      emptyEl.textContent = 'The router accepted the scan but returned no data. ' +
        'Some RouterOS builds do not emit frequency-scan results over the API, ' +
        'even though the same scan works in WinBox.';
      setStatus('No data returned by the router', false);
      return;
    }
    setStatus(msg + (d.truncated ? ' (truncated)' : ''), false);
  });

  socket.on('wifiscan:error', function (d) {
    if (!d) return;
    setScanning(false);
    var msg = {
      busy:               'Another scan is already running on this router' + (d.iface ? (' (' + d.iface + ')') : ''),
      'fleet-busy':       'Too many scans running at once — try again shortly',
      cooldown:           'Please wait a few seconds before scanning again',
      denied:             'You do not have permission to scan this router',
      'bad-request':      'Invalid scan request',
      'no-such-interface': 'That interface no longer exists',
      'capsman-managed':  'This radio is managed by CAPsMAN — scan it from its manager',
      'not-a-radio':      'That is a virtual AP, not a radio',
      unavailable:        'Wireless collection is not running for this router',
      'router-offline':   'The router is not connected',
      'permission-denied': 'The RouterOS user needs the "test" policy to run a scan',
      'unsupported-stack': 'This router uses the legacy wireless package, which is not supported',
    }[d.code] || (d.message || 'Scan failed');
    setStatus(msg, false);
  });

  // Ask again on page entry so the button reflects the current router.
  document.addEventListener('mikrodash:pagechange', function (e) {
    if (e.detail === 'wireless') socket.emit('wifiscan:interfaces');
  });
}());

/* ── VLANs page (issue #32) ───────────────────────────────────────────────────
   Rates arrive already joined server-side from interfaceStatus, so this file
   never sees an interface object — only VLAN-shaped rows. See src/collectors/
   vlans.js for why that join does not happen in the browser. */
(function () {
  var tbody = $('vlansTable'), theadRow = $('vlansThead');
  if (!tbody || !theadRow) return;

  var _data = null;
  var _sort = { col: 'vlanId', dir: 'asc' };
  var _showDynamic = false;

  var COLS = [
    { key:'vlanId',   label:'VLAN' },
    { key:'name',     label:'Interface' },
    { key:'parent',   label:'Parent' },
    { key:'mtu',      label:'MTU' },
    { key:'tagged',   label:'Tagged Ports' },
    { key:'untagged', label:'Untagged Ports' },
    { key:'clients',  label:'Clients' },
    { key:'rate',     label:'RX / TX' },
  ];

  function sortVal(v, key) {
    if (key === 'vlanId')  return v.vlanId;
    if (key === 'clients') return v.clients || 0;
    if (key === 'mtu')     return (v.interfaces[0] && v.interfaces[0].mtu) || 0;
    if (key === 'rate')    return (v.rxMbps || 0) + (v.txMbps || 0);
    if (key === 'name')    return (v.name || '').toLowerCase();
    if (key === 'parent')  return ((v.interfaces[0] && v.interfaces[0].parent) || '').toLowerCase();
    if (key === 'tagged')  return v.tagged.length;
    return v.untagged.length;
  }

  function ports(list) {
    if (!list.length) return '<span style="color:var(--text-muted)">&mdash;</span>';
    return list.map(function (n) { return '<span class="wl-band wl-band-5">' + esc(n) + '</span>'; }).join(' ');
  }

  // Per-VLAN rate history for the sparklines, kept here rather than server-side:
  // it is presentation state, and the collector already ships every sample the
  // line needs. Pushed once per update, never on re-render, or sorting or typing
  // in the search box would forge samples the router never sent.
  var _hist = {};           // vlanId -> { rx:[], tx:[] }
  var HIST_MAX = 40;

  function pushHistory(d) {
    var live = {};
    d.vlans.forEach(function (v) {
      live[v.vlanId] = true;
      var h = _hist[v.vlanId] || (_hist[v.vlanId] = { rx: [], tx: [] });
      // A null rate is "not reported", so the line holds its last value rather
      // than dropping to zero and drawing a cliff that never happened.
      if (v.rxMbps !== null) h.rx.push(v.rxMbps);
      if (v.txMbps !== null) h.tx.push(v.txMbps);
      if (h.rx.length > HIST_MAX) h.rx.splice(0, h.rx.length - HIST_MAX);
      if (h.tx.length > HIST_MAX) h.tx.splice(0, h.tx.length - HIST_MAX);
    });
    // Drop VLANs that no longer exist, so a deleted-and-recreated VLAN does not
    // inherit the old one's trend line.
    Object.keys(_hist).forEach(function (k) { if (!live[k]) delete _hist[k]; });
  }

  // Stroked with currentColor and coloured by class, so the line cannot drift
  // from the value above it: --accent-tx is green in this theme, and a
  // hardcoded stroke was already wrong.
  function spark(history, dir) {
    if (!history || history.length < 2) return '<span class="vlan-spark-slot"></span>';
    var w = 56, h = 14, pad = 1.5;
    var max = Math.max.apply(null, history) || 1;   // baseline always zero, so
    var pts = history.map(function (v, i) {         // a rise reads as a rise
      var x = pad + (i / (history.length - 1)) * (w - pad * 2);
      var y = h - pad - (v / max) * (h - pad * 2);
      return x.toFixed(1) + ',' + y.toFixed(1);
    });
    return '<svg class="vlan-spark ' + dir + '" width="' + w + '" height="' + h + '" viewBox="0 0 ' + w + ' ' + h + '">' +
      '<polyline points="' + pts.join(' ') + '" fill="none" stroke="currentColor"' +
      ' stroke-width="1.3" stroke-linejoin="round" stroke-linecap="round"/></svg>';
  }

  function rateLine(dir, mbps, history) {
    var cls = (mbps ? dir : 'zero');
    return '<div class="vlan-rate-line">' +
      '<span class="vlan-rate-arrow ' + cls + '">' + (dir === 'rx' ? '\u2193' : '\u2191') + '</span>' +
      '<span class="vlan-rate-val ' + cls + '">' + fmtMbps(mbps || 0) + '</span>' +
      // The line keeps its direction colour even at zero: it is showing the
      // trend that got here, not the current reading.
      spark(history, dir) +
    '</div>';
  }

  // null is "the router did not report a rate", which is not the same as idle.
  function rate(v) {
    if (v.rxMbps === null && v.txMbps === null) {
      return '<span style="color:var(--text-muted)" title="Interface rates are unavailable">&mdash;</span>';
    }
    var h = _hist[v.vlanId] || { rx: [], tx: [] };
    return '<div class="vlan-rate">' +
      rateLine('rx', v.rxMbps, h.rx) +
      rateLine('tx', v.txMbps, h.tx) +
    '</div>';
  }

  function render() {
    if (!_data) return;
    var q = ($('vlansSearch') && $('vlansSearch').value || '').toLowerCase().trim();
    var rows = _data.vlans.filter(function (v) {
      if (!q) return true;
      return String(v.vlanId).indexOf(q) === 0 || (v.name || '').toLowerCase().indexOf(q) !== -1 ||
             v.tagged.concat(v.untagged).some(function (p) { return p.toLowerCase().indexOf(q) !== -1; });
    });
    rows = rows.slice().sort(function (a, b) {
      var av = sortVal(a, _sort.col), bv = sortVal(b, _sort.col);
      if (typeof av === 'string') return _sortMul(_sort) * av.localeCompare(bv);
      return _sortMul(_sort) * (av - bv);
    });

    _renderSortHeader('vlansThead', COLS, _sort, function () { render(); });

    $('vlansBadge').textContent = _data.vlans.length;
    $('vlansBadge').className = 'card-badge' + (_data.vlans.length ? ' active-blue' : '');

    tbody.innerHTML = rows.length ? rows.map(function (v) {
      var i0 = v.interfaces[0];
      // A VLAN that exists only at layer 2 — membership via a bridge port's
      // pvid, with no /interface/vlan row — has nothing to edit, so it gets no
      // data-id and is simply not clickable.
      return '<tr' + resRow(i0 && i0.id, i0 && i0.name) + '>' +
        '<td><span class="wl-band wl-band-24">' + v.vlanId + '</span></td>' +
        '<td>' + (v.name ? esc(v.name) : '<span style="color:var(--text-muted)">no L3 interface</span>') + '</td>' +
        '<td>' + esc(i0 ? i0.parent : '') + '</td>' +
        '<td>' + (i0 && i0.mtu ? i0.mtu : '&mdash;') + '</td>' +
        '<td>' + ports(v.tagged) + '</td>' +
        '<td>' + ports(v.untagged) + '</td>' +
        '<td>' + (v.clients || 0) + '</td>' +
        '<td>' + rate(v) + '</td>' +
      '</tr>';
    }).join('') : '<tr><td colspan="8" class="empty-state">No VLANs configured on this router.</td></tr>';

    renderBridge();
  }

  function renderBridge() {
    var tb = $('vlansBridgeTable'); if (!tb || !_data) return;
    // Dynamic rows are filtered HERE, at render. They are kept in the join
    // because on a real router most VLAN membership comes from them — filtering
    // them earlier would show every VLAN with no tagged ports.
    var rows = _data.bridgeVlans.filter(function (r) { return _showDynamic || !r.dynamic; });
    $('vlansBridgeBadge').textContent = rows.length;
    $('vlansDynChip').textContent = _data.dynamicCount;
    tb.innerHTML = rows.length ? rows.map(function (r) {
      // Dynamic rows carry the same weight as static ones: the "dynamic" pill
      // already says which is which, and dimming them made real membership
      // harder to read for no added information.
      return '<tr>' +
        '<td>' + esc(r.bridge) + '</td>' +
        '<td><span class="wl-band wl-band-24">' + esc(r.raw) + '</span></td>' +
        '<td>' + ports(r.tagged) + '</td>' +
        '<td>' + ports(r.untagged) + '</td>' +
        '<td>' + (r.dynamic ? '<span class="wl-band wl-band-6">dynamic</span>'
                            : '<span class="wl-band wl-band-5">static</span>') + '</td>' +
      '</tr>';
    }).join('') : '<tr><td colspan="5" class="empty-state">No bridge VLAN entries.</td></tr>';
  }

  function renderSummary() {
    if (!_data) return;
    var tagged = new Set(), untagged = new Set();
    var rx = 0, tx = 0, any = false;
    _data.vlans.forEach(function (v) {
      v.tagged.forEach(function (p) { tagged.add(p); });
      v.untagged.forEach(function (p) { untagged.add(p); });
      if (v.rxMbps !== null) { rx += v.rxMbps; any = true; }
      if (v.txMbps !== null) { tx += v.txMbps; any = true; }
    });
    $('vlSumCount').textContent    = _data.vlans.length;
    $('vlSumTagged').textContent   = tagged.size;
    $('vlSumUntagged').textContent = untagged.size;
    $('vlSumRate').innerHTML = any ? fmtMbps(rx + tx) : '&mdash;';
  }

  socket.on('vlans:update', function (d) {
    if (!d) return;
    _data = d;
    pushHistory(d);
    renderSummary();
    if (pageVisible('vlans')) render();
  });

  document.addEventListener('mikrodash:pagechange', function (e) {
    if (e.detail === 'vlans' && _data) render();
  });

  var se = $('vlansSearch');
  if (se) se.addEventListener('input', _debounce(render, 150));
  var dyn = $('vlansShowDynamic');
  if (dyn) dyn.addEventListener('change', function () { _showDynamic = dyn.checked; renderBridge(); });
}());

