      if (k === 'changes' || k === 'note') return;
      bits.push('<span style="color:var(--text-muted)">' + esc(k) + '</span> ' + esc(_short(d[k])));
    });
    if (d.note) bits.push('<span style="color:var(--text-muted)">' + esc(d.note) + '</span>');
