    return {
      ts: r.ts, actor: r.actor_name || '', ip: r.actor_ip || '',
      action: r.action || '', target: r.target_name || r.target_id || '',
      outcome: r.outcome || '', detail: r.detail || '', router_id: r.router_id || '',
