        '<td class="mono" style="color:var(--text-muted)">' + esc(r.ip || '—') + '</td>' +
        '<td>' + esc(r.action) + '</td>' +
        '<td>' + (r.target ? esc(r.target) : '<span style="color:var(--text-muted)">&mdash;</span>') +
          // The pill names the device. It used to read the literal word
