  }
  if (ddSearch) {
    ddSearch.addEventListener('input', function() {
      _ddFilter = ddSearch.value; _ddHl = -1; renderDropdown();
    });
  }
  if (ddWrap) {
    ddWrap.addEventListener('keydown', function(e) {
      if (!_ddOpen) {
        if (e.key === 'Enter' || e.key === ' ' || e.key === 'ArrowDown') { e.preventDefault(); openDropdown(); }
