  function loadSchedules() {
    if (!rptRouter || !rptRouter.value) return;
    schedApi('', {}).then(function(d) {
      if (!d || !d.ok) return;
      _sched.rows = d.schedules || [];
      _sched.permitted = !!d.permitted;
