        '<td>' + esc(u.name) + (u.comment ? '<div class="muted-note">' + esc(u.comment) + '</div>' : '') + '</td>' +
        '<td>' + esc(u.group) + '</td>' +
        '<td>' + (u.address ? esc(u.address) : dash()) + '</td>' +
        '<td style="color:var(--text-muted)">' + (u.lastLogin ? esc(u.lastLogin) : dash()) + '</td>' +
        '<td>' + status + '</td>' +
        '<td>' + (u.protected ? lockCell('account')
