      return '<tr>' +
        '<td>' + esc(g.name) + (g.comment ? '<div class="muted-note">' + esc(g.comment) + '</div>' : '') + '</td>' +
        '<td>' + pol + '</td>' +
        '<td>' + g.members + '</td>' +
        '<td>' + (g.protected ? lockCell('group')
