    // anyway; leaving them in the list only invites the refusal.
    var sel = $('ruf_group');
    sel.innerHTML = (_data && _data.groups || []).filter(function (g) { return !g.protected; })
      .map(function (g) {
        return '<option value="' + esc(g.name) + '"' + (u && u.group === g.name ? ' selected' : '') + '>' +
               esc(g.name) + '</option>';
