      create: 'Created ', update: 'Updated ', 'delete': 'Removed ',
      'group-create': 'Created group ', 'group-update': 'Updated group ', 'group-delete': 'Removed group ',
      'session-remove': 'Ended the session for ',
    }[d && d.action] || 'Done: ';
