        '<td class="text-center" style="padding-right:0">' +
          '<input type="checkbox" class="bk-pick" data-bk-pick="' + r.id + '"' +
          (picked ? ' checked' : '') + (pickable ? '' : ' disabled') +
          ' aria-label="Select this restore point">' +
